class Solution {
public:
    vector<int> shortestDistanceAfterQueries(int n, vector<vector<int>>& queries) {
        vector<vector<int>> adj(n);
        for (int i = 0; i + 1 < n; ++i) {
            adj[i].push_back(i + 1);
        }
        vector<int> ans;
        ans.reserve(queries.size());
        for (auto& q : queries) {
            adj[q[0]].push_back(q[1]);
            vector<int> dist(n, -1);
            queue<int> bq;
            dist[0] = 0;
            bq.push(0);
            while (!bq.empty()) {
                int u = bq.front();
                bq.pop();
                if (u == n - 1) break;
                for (int v : adj[u]) {
                    if (dist[v] == -1) {
                        dist[v] = dist[u] + 1;
                        bq.push(v);
                    }
                }
            }
            ans.push_back(dist[n - 1]);
        }
        return ans;
    }
};
